// Dedupes against n8n's own workflow memory (global static data) -- no external database, same
// pattern as the Duplicate-Contact Watchdog (PAC-55). Tracks which matter IDs this workflow has already
// set up so a matter is never processed twice, even though every poll re-fetches every open matter.
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedMatterIds) staticData.processedMatterIds = {}; // matter_id -> ISO processed_at

const response = $input.first().json;
const matters = response.data || [];

if (!staticData.initialized) {
  // First run after activation: mark every currently-open matter as already-seen WITHOUT running
  // setup on it -- otherwise activating this template would fire folder/doc/task/deadline creation
  // for every matter the firm has ever opened, all at once.
  matters.forEach(m => { staticData.processedMatterIds[m.id] = new Date().toISOString(); });
  staticData.initialized = true;
  return [{ json: { new_matters: [], new_matter_count: 0, has_new_matters: false, bootstrap: true } }];
}

const newMatters = matters.filter(m => !staticData.processedMatterIds[m.id]);
newMatters.forEach(m => { staticData.processedMatterIds[m.id] = new Date().toISOString(); });

return [{ json: {
  new_matters: newMatters,
  new_matter_count: newMatters.length,
  has_new_matters: newMatters.length > 0,
  bootstrap: false,
} }];

// Turns the new_matters array into one n8n item per matter -- everything downstream through the
// summary email processes one matter at a time.
return $input.first().json.new_matters.map(m => ({ json: {
  matter_id: m.id,
  matter_display_number: m.display_number,
  matter_description: m.description || '',
  practice_area: (m.practice_area && m.practice_area.name) || '',
  open_date: (m.open_date || new Date().toISOString().slice(0, 10)),
  client_name: (m.client && m.client.name) || '',
  attorney_email: (m.responsible_attorney && m.responsible_attorney.email) || '',
} }));

// Explicit node references throughout this workflow (rather than $json) because every Drive/Clio
// API call replaces the item's data with its own response.
// 'Search For Existing Matter Folder' has Always Output Data on, so a zero-match search still
// delivers one item -- an empty placeholder, not a real folder. Checking for a real 'id' field
// (not just item presence) is what tells the two cases apart.
const meta = $('Split New Matters Into Items').item.json;
const results = $input.all();
const found = results.length > 0 && results[0].json && results[0].json.id ? results[0].json : null;

return [{ json: {
  ...meta,
  existing_folder_id: found ? found.id : null,
  folder_exists: !!found,
} }];

// Edit this list to match your firm's standard matter folder structure.
const DEFAULT_FOLDERS = ['Correspondence', 'Pleadings & Filings', 'Client Documents', 'Billing & Trust', 'Signed Agreements'];

const meta = $('Check Matter Folder Existence').item.json;
const input = $input.first().json;
// If this ran right after 'Create Matter Root Folder', input.id is the new folder's id.
// If it ran right after the 'folder exists' branch (unchanged pass-through from 'If Matter Folder
// Found'), meta.existing_folder_id is already set.
const matter_folder_id = input.id || meta.existing_folder_id;

return DEFAULT_FOLDERS.map(name => ({ json: { ...meta, matter_folder_id, subfolder_name: name } }));

const items = $input.all();
const meta = $('Build Standard Subfolder List').first().json; // matter fields + matter_folder_id, same for every item
const subfolder_names = items.map(i => i.json.name).filter(Boolean);

return [{ json: {
  matter_id: meta.matter_id,
  matter_display_number: meta.matter_display_number,
  matter_description: meta.matter_description,
  practice_area: meta.practice_area,
  open_date: meta.open_date,
  client_name: meta.client_name,
  attorney_email: meta.attorney_email,
  matter_folder_id: meta.matter_folder_id,
  matter_folder_link: `https://drive.google.com/drive/folders/${meta.matter_folder_id}`,
  subfolders_created: subfolder_names,
  subfolder_count: subfolder_names.length,
} }];

// Edit these three maps to match your firm's own template library, standard task list, and
// intake deadline rules. Keyed by practice_area -- must match the practice area name exactly as it
// appears in Clio (Settings → Practice Areas). Any practice area left out of a map simply skips
// that step for matters in it -- not an error.
const DOC_TEMPLATE_MAP = {
  'Family Law': [
    { doc_label: 'Matter Opening Checklist', template_var: 'TEMPLATE_MATTER_CHECKLIST_DOC_ID' },
  ],
  'Personal Injury': [
    { doc_label: 'Matter Opening Checklist', template_var: 'TEMPLATE_MATTER_CHECKLIST_DOC_ID' },
    { doc_label: 'Case Plan', template_var: 'TEMPLATE_CASE_PLAN_DOC_ID' },
  ],
  'Estate Planning': [
    { doc_label: 'Matter Opening Checklist', template_var: 'TEMPLATE_MATTER_CHECKLIST_DOC_ID' },
  ],
  // Add a row per practice area your firm handles.
};

const TASK_LIST_MAP = {
  'Family Law': [
    { name: 'Send engagement letter', offset_days: 1 },
    { name: 'Run conflict check', offset_days: 0 },
    { name: 'Open trust ledger', offset_days: 2 },
  ],
  'Personal Injury': [
    { name: 'Send engagement letter', offset_days: 1 },
    { name: 'Run conflict check', offset_days: 0 },
    { name: 'Request medical records authorization', offset_days: 3 },
  ],
  'Estate Planning': [
    { name: 'Send engagement letter', offset_days: 1 },
    { name: 'Run conflict check', offset_days: 0 },
    { name: 'Send asset questionnaire', offset_days: 2 },
  ],
  // Add a row per practice area your firm handles.
};

// ⚙️ The firm owns every rule here -- this workflow never suggests or interprets a legal deadline,
// same ground rule as the Court Deadline Calculator (NTC-16). Replace the placeholders below.
const DEADLINE_RULE_MAP = {
  'Family Law': [
    { name: 'Example Deadline — replace this', offset_days: 21, offset_type: 'calendar', description: 'Placeholder — replace with your firm rule (e.g. response deadline per local rules)' },
  ],
  'Personal Injury': [
    { name: 'Example Deadline — replace this', offset_days: 30, offset_type: 'business', description: 'Placeholder — replace with your firm rule (e.g. statute-of-limitations check-in)' },
  ],
  'Estate Planning': [
    { name: 'Example Deadline — replace this', offset_days: 14, offset_type: 'calendar', description: 'Placeholder — replace with your firm rule (e.g. document review follow-up)' },
  ],
  // Add a row per practice area your firm handles.
};

const meta = $input.first().json;

const docs = (DOC_TEMPLATE_MAP[meta.practice_area] || [])
  .map(d => ({ doc_label: d.doc_label, template_doc_id: $vars[d.template_var] }))
  .filter(d => !!d.template_doc_id); // skip any template the firm hasn't configured a Variable for yet

const tasks = TASK_LIST_MAP[meta.practice_area] || [];
const deadline_rules = DEADLINE_RULE_MAP[meta.practice_area] || [];

return [{ json: {
  ...meta,
  docs, doc_count: docs.length, has_docs: docs.length > 0,
  tasks, task_count: tasks.length, has_tasks: tasks.length > 0,
  deadline_rules, deadline_count: deadline_rules.length, has_deadlines: deadline_rules.length > 0,
} }];

// Builds the batchUpdate requests that replace {{merge_tag}} placeholders in the copied template
// with this matter's actual field values. Add a row here for every merge tag your firm's internal
// templates use.
const item = $('Split Doc Template List Into Items').item.json;
const newDocId = $input.item.json.id; // from Copy Doc Template To Matter Folder's response

const MERGE_FIELDS = {
  '{{matter_display_number}}': item.matter_display_number,
  '{{matter_description}}': item.matter_description,
  '{{client_name}}': item.client_name,
  '{{practice_area}}': item.practice_area,
  '{{open_date}}': item.open_date,
};

const requests = Object.entries(MERGE_FIELDS).map(([tag, value]) => ({
  replaceAllText: { containsText: { text: tag, matchCase: true }, replaceText: String(value || '') },
}));

return { json: { ...item, new_doc_id: newDocId, batch_requests: requests } };

// Update Doc Merge Fields' own response ({documentId, replies}) replaced the item's json, so 
// doc_label and new_doc_id are read back explicitly from 'Build Doc Merge Requests' rather than $json.
const item = $('Build Doc Merge Requests').item.json;
return { json: { doc_result: true, doc_label: item.doc_label, new_doc_id: item.new_doc_id } };

// Both the 'has templates' and 'no templates' branches converge here. Reads the full matter/practice-area
// config back from 'Determine Practice Area Setup Config' so it carries forward into the task and
// deadline stages regardless of which branch ran.
const config = $('Determine Practice Area Setup Config').first().json;
const items = $input.all();
const first = items[0].json;

let docs_created = [];
if ('doc_result' in first) {
  docs_created = items.map(i => ({ label: i.json.doc_label, link: `https://docs.google.com/document/d/${i.json.new_doc_id}/edit` }));
}

return [{ json: { ...config, docs_created, doc_setup_count: docs_created.length } }];

const { docs, doc_count, has_docs, docs_created, doc_setup_count, tasks, task_count, has_tasks, deadline_rules, deadline_count, has_deadlines, ...meta } = $input.first().json;

function addCalendarDays(dateStr, n) {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + Number(n || 0));
  return d.toISOString().slice(0, 10);
}

return tasks.map(t => ({ json: {
  ...meta,
  task_name: t.name,
  offset_days: t.offset_days,
  due_date: addCalendarDays(meta.open_date, t.offset_days),
} }));

// Create Clio Matter Task's own response replaced the item's json -- task_name and due_date are
// read back explicitly from 'Split Task List Into Items'.
const item = $('Split Task List Into Items').item.json;
return { json: { task_result: true, task_name: item.task_name, due_date: item.due_date } };

const config = $('Aggregate Document Setup Results').first().json;
const items = $input.all();
const first = items[0].json;

let tasks_created = [];
if ('task_result' in first) {
  tasks_created = items.map(i => ({ name: i.json.task_name, due_date: i.json.due_date }));
}

return [{ json: { ...config, tasks_created, task_setup_count: tasks_created.length } }];

const { docs, doc_count, has_docs, docs_created, doc_setup_count, tasks, task_count, has_tasks, tasks_created, task_setup_count, deadline_rules, deadline_count, has_deadlines, ...meta } = $input.first().json;

// Same US federal holiday + business-day math as the Court Deadline Calculator (NTC-16) -- kept
// here directly so this template has zero dependency on NTC-16 being deployed.
function nthWeekday(year, month0, weekday, n) {
  if (n > 0) {
    const d = new Date(Date.UTC(year, month0, 1));
    let count = 0;
    while (true) { if (d.getUTCDay() === weekday) { count++; if (count === n) return new Date(d); } d.setUTCDate(d.getUTCDate() + 1); }
  } else {
    const d = new Date(Date.UTC(year, month0 + 1, 0));
    while (true) { if (d.getUTCDay() === weekday) return new Date(d); d.setUTCDate(d.getUTCDate() - 1); }
  }
}
function getUSFederalHolidays(year) {
  const set = new Set();
  function addObserved(date) {
    const d = new Date(date);
    const day = d.getUTCDay();
    if (day === 6) d.setUTCDate(d.getUTCDate() - 1);
    if (day === 0) d.setUTCDate(d.getUTCDate() + 1);
    set.add(d.toISOString().slice(0, 10));
  }
  addObserved(new Date(Date.UTC(year, 0, 1)));
  addObserved(nthWeekday(year, 0, 1, 3));
  addObserved(nthWeekday(year, 1, 1, 3));
  addObserved(nthWeekday(year, 4, 1, -1));
  addObserved(new Date(Date.UTC(year, 5, 19)));
  addObserved(new Date(Date.UTC(year, 6, 4)));
  addObserved(nthWeekday(year, 8, 1, 1));
  addObserved(nthWeekday(year, 9, 1, 2));
  addObserved(new Date(Date.UTC(year, 10, 11)));
  addObserved(nthWeekday(year, 10, 4, 4));
  addObserved(new Date(Date.UTC(year, 11, 25)));
  return set;
}
const holidayCache = {};
function isBusinessDay(dateStr) {
  const d = new Date(dateStr + 'T12:00:00Z');
  const dow = d.getUTCDay();
  if (dow === 0 || dow === 6) return false;
  const yr = d.getUTCFullYear();
  if (!holidayCache[yr]) holidayCache[yr] = getUSFederalHolidays(yr);
  return !holidayCache[yr].has(dateStr);
}
function addBusinessDays(startDateStr, n) {
  const direction = n >= 0 ? 1 : -1;
  const steps = Math.abs(n);
  const d = new Date(startDateStr + 'T12:00:00Z');
  let counted = 0;
  while (counted < steps) { d.setUTCDate(d.getUTCDate() + direction); if (isBusinessDay(d.toISOString().slice(0, 10))) counted++; }
  return d.toISOString().slice(0, 10);
}
function addCalendarDays(startDateStr, n) {
  const d = new Date(startDateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

return deadline_rules.map(rule => {
  const offsetType = (rule.offset_type || 'calendar').toLowerCase();
  const deadline_date = offsetType === 'business'
    ? addBusinessDays(meta.open_date, Number(rule.offset_days) || 0)
    : addCalendarDays(meta.open_date, Number(rule.offset_days) || 0);
  return { json: { ...meta, rule_name: rule.name, deadline_date, description: rule.description || rule.name } };
});

// Create Clio Calendar Deadline's own response replaced the item's json -- rule_name and
// deadline_date are read back explicitly from 'Compute Intake Deadlines'.
const item = $('Compute Intake Deadlines').item.json;
return { json: { deadline_result: true, rule_name: item.rule_name, deadline_date: item.deadline_date } };

const config = $('Aggregate Task Setup Results').first().json;
const items = $input.all();
const first = items[0].json;

let deadlines_created = [];
if ('deadline_result' in first) {
  deadlines_created = items.map(i => ({ name: i.json.rule_name, date: i.json.deadline_date }));
}

return [{ json: { ...config, deadlines_created, deadline_setup_count: deadlines_created.length } }];
